# install - PWOS5 一体化安装器（手动填编码版）
import os
import sys
import time
import base64
import zlib

# ============================================================
# 第一步：把编码数据填到这里
# ============================================================
# 打开 PWOS5_encoded.txt，全选复制，替换下面的 "" 内容
_MAIN_ENCODED = """

"""

# 打开 std_lib_encoded.txt，全选复制，替换下面的 "" 内容
_STD_ENCODED = """

"""
# ============================================================

class PWOSInstaller:
    def __init__(self):
        self.files = {
            "main": {
                "name": "PWOS5 主系统",
                "filename": "PWOS5.py",
                "encoded": _MAIN_ENCODED.strip(),
            },
            "std": {
                "name": "STD 标准库",
                "filename": "std_lib.py",
                "encoded": _STD_ENCODED.strip(),
            }
        }
        self.selected_files = []
        self.install_path = ""

    # ========== 工具函数 ==========
    @staticmethod
    def decode_and_write(encoded_data, target_path):
        """解码 Base64 → 解压 zlib → 写入文件"""
        if not encoded_data:
            raise ValueError("编码数据为空")
        compressed = base64.b64decode(encoded_data)
        content = zlib.decompress(compressed).decode('utf-8')
        with open(target_path, 'w', encoding='utf-8') as f:
            f.write(content)
        return len(content)

    @staticmethod
    def loading_animation(message="正在加载", duration=0.8):
        chars = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']
        end_time = time.time() + duration
        i = 0
        while time.time() < end_time:
            print(f"\r{chars[i % len(chars)]} {message}...", end="")
            i += 1
            time.sleep(0.1)
        print("\r" + " " * 50 + "\r", end="")

    @staticmethod
    def progress_bar(current, total, bar_length=40):
        percent = current / total if total > 0 else 0
        filled = int(bar_length * percent)
        bar = "█" * filled + "░" * (bar_length - filled)
        return f"[{bar}] {percent * 100:.1f}%"

    # ========== 显示菜单 ==========
    def show_menu(self):
        print("\n" + "=" * 60)
        print("     PWOS5 安装引导器 v2.0")
        print("=" * 60)
        print("检测到以下安装文件：")
        
        for key, info in self.files.items():
            size_kb = len(info["encoded"]) // 1024
            print(f"  📄 {info['name']} ({info['filename']}) - 大小: {size_kb} KB")
        
        print("\n请选择安装选项：")
        print("  [1] 仅安装主系统")
        print("  [2] 仅安装 STD 库")
        print("  [3] 全部安装（推荐）")
        print("  [4] 退出")

    def get_user_choice(self):
        while True:
            choice = input("\n请输入选择 (1-4): ").strip()
            if choice == "1":
                self.selected_files = ["main"]
                return True
            elif choice == "2":
                self.selected_files = ["std"]
                return True
            elif choice == "3":
                self.selected_files = ["main", "std"]
                return True
            elif choice == "4":
                print("安装已取消")
                return False
            else:
                print("❌ 无效输入，请重新选择")

    # ========== 获取安装路径 ==========
    def get_install_path(self):
        default_path = os.path.join(os.getcwd(), "PWOS5")
        path = input(f"\n请输入安装路径（默认: {default_path}）: ").strip()
        if not path:
            path = default_path
        try:
            os.makedirs(path, exist_ok=True)
            self.install_path = path
            print(f"✅ 已选择安装路径: {path}")
            return True
        except Exception as e:
            print(f"❌ 创建目录失败: {e}")
            return False

    # ========== 带进度条的安装 ==========
    def install_with_progress(self, file_key):
        file_info = self.files[file_key]
        encoded_data = file_info["encoded"]
        
        if not encoded_data:
            print(f"❌ {file_info['name']} 编码数据为空，跳过")
            return False

        print(f"\n🔄 正在解压 {file_info['name']}...")
        
        try:
            # 解码
            compressed = base64.b64decode(encoded_data)
            total_steps = 20
            data_len = len(compressed)
            chunk_size = max(1, data_len // total_steps)
            
            # 分块解压（模拟进度）
            decompressed_parts = []
            for step in range(total_steps + 1):
                start = step * chunk_size
                end = min((step + 1) * chunk_size, data_len)
                chunk = compressed[start:end]
                if chunk:
                    decompressed_parts.append(chunk)
                bar = self.progress_bar(step, total_steps)
                estimated_time = max(1, data_len / 200000)
                remaining = max(0, estimated_time * (1 - step / total_steps))
                print(f"\r  {bar} - 预计剩余: {remaining:.1f}秒", end="")
                time.sleep(0.12)
            
            # 合并并解压
            full_compressed = b''.join(decompressed_parts)
            content = zlib.decompress(full_compressed).decode('utf-8')
            
            # 写入文件
            target_file = os.path.join(self.install_path, file_info['filename'])
            with open(target_file, 'w', encoding='utf-8') as f:
                f.write(content)
            
            print(f"\n✅ {file_info['name']} 安装完成！")
            print(f"   📄 已写入: {target_file}")
            print(f"   📊 文件大小: {len(content) / 1024:.2f} KB")
            return True
            
        except Exception as e:
            print(f"\n❌ 安装失败: {e}")
            return False

    # ========== 主流程 ==========
    def run(self):
        self.show_menu()
        if not self.get_user_choice():
            return

        if not self.get_install_path():
            return

        print("\n" + "=" * 60)
        print("安装确认：")
        print(f"  安装路径: {self.install_path}")
        print(f"  安装文件: {', '.join([self.files[k]['name'] for k in self.selected_files])}")
        print("=" * 60)
        confirm = input("确认安装? (Y/n): ").strip().lower()
        if confirm == 'n':
            print("安装已取消")
            return

        self.loading_animation("正在准备安装文件", duration=1.0)

        success_count = 0
        for key in self.selected_files:
            if self.install_with_progress(key):
                success_count += 1

        print("\n" + "=" * 60)
        if success_count == len(self.selected_files):
            print("✅ 全部安装完成！")
        else:
            print(f"⚠️ 部分安装成功 ({success_count}/{len(self.selected_files)})")
        print(f"安装路径: {self.install_path}")
        print("\n现在可以运行: python PWOS5.py")
        print("=" * 60)

        run_now = input("\n是否立即运行 PWOS5？(Y/n): ").strip().lower()
        if run_now != 'n':
            os.chdir(self.install_path)
            os.system('python PWOS5.py')

if __name__ == "__main__":
    installer = PWOSInstaller()
    installer.run()